#!/usr/bin/env python3
"""Translate literal font bytes and MultiConfig02 layout into C data, not code."""
from pathlib import Path
import re,struct
root=Path(__file__).resolve().parents[1]
font=[]
for line in (root/'reference/IBMGR.ASM').read_text(encoding='latin1').splitlines():
 m=re.search(r'\bdc\.b\s+(\S+)',line,re.I)
 if m:
  for s in m[1].split(','):
   if s.startswith('%'): v=int(s[1:],2)
   else: v=sum(int(x) for x in re.findall(r'[+-]?\d+',s))
   font.append(v&255)
(root/'src/font.c').write_text('/* Literal IBMGR.ASM font, GPL-3.0-or-later. */\n#include "qlterm.h"\nconst U8 gr_set1[] = {\n'+''.join('    '+','.join(str(v) for v in font[i:i+18])+',\n' for i in range(0,len(font),18))+'};\n')
# Value, type, ID, selection key, label, attributes. Values retain source defaults.
items=[]
def item(name,typ,id,key,label,value,attr): items.append((name,typ,id,key,label,value,attr))
for name,id,key,label,value,lo,hi in [('X','1','X','X Position of top left corner',14,0,511),('Y','2','Y','Y Position of top left corner',2,0,255),('COLS','3','W','Terminal width in characters',80,80,255),('ROWS','4','H','Terminal height in characters',24,24,127)]: item(name,'word','QLT'+id,key,label,value,(lo,hi))
for name,id,label,v in [('PAPER','5','Default paper colour',0),('INK','6','Default ink colour',7),('BORDER','7','Border colour',2)]:item(name,'byte','QLT'+id,0,label,v,(0,255))
item('BAUD','code','QLT9','B','Default baud rate',4,[(i,k,s) for i,(k,s) in enumerate(zip('0123456789AB',['NONE','300','600','1200','2400','4800','9600','19200','38400','57600','115200','12H75']))])
for name,id,label,v in [('INIT','L','Modem initialisation','ATZ|'),('PREFIX','M','Modem dial prefix','ATD'),('POSTFIX','N','Modem dial postfix','|'),('HANGUP','O','Modem hang-up command','~~+++~~ATH0|')]:item(name,'string','QLT'+id,0,label,v,32)
item('RXBUF','word','QLTR','D','Receive buffer size (KB)',64,(0,128))
item('DLBUF','word','QLT8','D','Download buffer size (KB)',32,(0,64))
for name,id,key,label,v,options in [
 ('ECHO','A','E','Default Local Echo setting',-1,[(-1,'0','Echo Off'),(0,'1','Echo On'),(1,'L','Local Only')]),
 ('TERM','B','T','Default terminal type',1,[(-1,'S','ASCII'),(0,'V','VT52'),(1,'A','VT100/ANSI')]),
 ('COLOUR','C','C','Default colour display',-1,[(-1,'B','Automatic'),(0,'4','4-colour'),(1,'8','8-colour')]),
 ('ENTER','P',0,'ENTER key sends',0,[(0,'0','CR'),(1,'1','LF'),(2,'2','CR+LF')]),
 ('DEL','Q',0,'BACKSPACE key sends',1,[(0,'0','CTRL-H (8)'),(1,'1','DEL (127)')]),
 ('CONVLF','D',0,'Default EOL conversion for Log & Transmit',1,[(0,'N','No'),(1,'Y','Yes')]),
 ('BELL','E',0,'Sound on BEL',1,[(0,'N','No'),(1,'Y','Yes')]),
 ('COOKED','F','L','Default logging',1,[(0,'R','Raw'),(1,'C','Cooked')]),
 ('PORT','G','S','Default communication device',6,[(i,str(i),s) for i,s in enumerate(['SER1I','SER1H','SER2I','SER2H','Custom','RAW TCP','Telnet'])])]:item(name,'code','QLT'+id,key,label,v,options)
item('CUSTOM','string','QLTH',0,'Custom communication device','SER3',48)
item('OPENMODE','byte','QLTI',0,'Mode for opening SER/TCP port',1,(0,255))
item('TRA','code','QLTR',0,'Turn off SER translation during file transfers',0,[(0,'N','No'),(1,'Y','Yes')])
item('PROTO','code','QLTJ',0,'Default file transfer protocol',2,[(0,'X','Xmodem'),(1,'1','Xmodem-1K'),(2,'Y','Ymodem'),(3,'G','Ymodem-G')])
item('DLDIR','string','QLTK',0,'Download directory','RAM2_',48)
b=bytearray()
def word(n):b.extend(struct.pack('>H',n&65535))
def align():
 if len(b)%2:b.append(0)
def qstr(s):
 raw=s.encode('latin1');word(len(raw));b.extend(raw);align()
def ref(at,target):struct.pack_into('>h',b,at,target-at)
entries=[]
for title,begin,end in [('Window settings',0,7),('Modem settings',7,12),('Other settings',12,len(items))]:
 b.extend(b'<<QCFX>>02');qstr(title);qstr('3.00')
 for it in items[begin:end]:
  name,typ,id,key,label,value,attr=it
  b.extend(id.encode());b.extend([{'string':0,'code':4,'byte':8,'word':10}[typ],ord(key) if key else 0]);at=len(b);b.extend(bytes(10));entries.append((it,at))
 word(-1)
word(-1)
defines=[]
for it,at in entries:
 name,typ,id,key,label,value,attr=it
 align();ref(at+6,len(b));qstr(label)
 ref(at+8,len(b))
 if typ=='string':word(1)
 elif typ=='code':
  for v,k,s in attr:word(((v&255)<<8)|ord(k));qstr(s)
  word(-1)
 elif typ=='byte':b.extend(attr)
 else:
  for v in attr:word(v)
 align();ref(at,len(b));defines.append((name,len(b),typ))
 if typ=='string':
  word(attr);word(len(value));b.extend(value.encode()+bytes(attr-len(value)));align()
 elif typ=='word':word(value)
 else:b.append(value&255)
align()
(root/'src/config.c').write_text('/* Generated MultiConfig02 data. GPL-3.0-or-later. */\n#include "qlterm.h"\nU8 config_blob[] = {\n'+''.join('    '+','.join(str(v) for v in b[i:i+18])+',\n' for i in range(0,len(b),18))+'};\n')
(root/'src/config.h').write_text('/* Generated by tools/generate_data.py. */\nextern unsigned char config_blob[];\n'+''.join('#define CFG_%s %d\n'%(n,o) for n,o,t in defines)+'int cfg_byte(int off);\nint cfg_word(int off);\nvoid cfg_string(int off, char *out);\n')
print('Font:',len(font),'bytes; config:',len(b),'bytes;',len(items),'settings')

crc=[]
for line in (root/'reference/CRCCITT.ASM').read_text().splitlines():
 if 'DC.W' in line.upper():crc.extend(int(x,16) for x in re.findall(r'\$([0-9A-Fa-f]{4})',line))
assert len(crc)==256
(root/'src/crc_table.h').write_text('/* Exact CRCCITT.ASM table, GPL-3.0-or-later. */\nstatic const U16 crc_table[256] = {\n'+''.join('    '+','.join('0x%04x'%v for v in crc[i:i+8])+',\n' for i in range(0,256,8))+'};\n')
